import urllib.request,urllib.error,json
base='https://app.ontrackegy.com'
checks=[('/login','تسجيل الدخول','href="/forgot-password"'),('/register','إنشاء حساب شركة','action="/register"'),('/register?type=reseller','إنشاء حساب ريسيلر','name="kind" value="reseller"'),('/register?reseller=delta-voice','دلتا فويس','name="reseller" value="delta-voice"'),('/forgot-password','نسيت كلمة المرور','action="/forgot-password"'),('/reset-password?token=bad','رابط الاسترجاع غير صالح',''),('/verify-email?token=bad','تأكيد البريد الإلكتروني','action="/verify-email"'),('/change-password','تسجيل الدخول',''),('/','تسجيل الدخول','')]
out=[]
for path,expected,extra in checks:
 try:
  with urllib.request.urlopen(urllib.request.Request(base+path,headers={'User-Agent':'OnTrackWebAuthSmoke/1.0'}),timeout=5) as response:
   body=response.read(180000).decode('utf-8','replace')
   out.append({'route':path,'status':response.status,'expected':expected in body,'form_or_scope':extra in body if extra else True})
 except urllib.error.HTTPError as e:out.append({'route':path,'status':e.code,'expected':False})
 except Exception as e:out.append({'route':path,'error':type(e).__name__,'expected':False})
print(json.dumps({'routes':out,'all_pass':all(x.get('status')==200 and x['expected'] and x['form_or_scope'] for x in out)},ensure_ascii=False))
